public class Cleaner_isValid_TriageGen2Test {

    private Cleaner cleaner;

    @Before
    public void setUp() {
        cleaner = new Cleaner(Whitelist.basic());
    }



    @Test
    public void testIsValidWithEmptyDocument() {
        Document emptyDocument = Document.createShell("");
        assertTrue(cleaner.isValid(emptyDocument));
    }











    private <T> T assertThrows(Class<T> exceptionClass, Runnable runnable) {
        try {
            runnable.run();
            return null;
        } catch (Throwable throwable) {
            if (exceptionClass.isInstance(throwable)) {
                return exceptionClass.cast(throwable);
            } else {
                throw new AssertionError("Expected exception of type " + exceptionClass.getName() + " but got " + throwable.getClass().getName());
            }
        }
    }
}
